import{_ as e}from"./chunks/08f-preview-office.BOqnux27.js";import{_ as a,o as r,c as o,a2 as d}from"./chunks/framework.D4up2k3b.js";const i="/filebox/docs/screenshots/08-preview-image.png",s="/filebox/docs/screenshots/08b-preview-markdown.png",n="/filebox/docs/screenshots/08c-preview-code.png",c="/filebox/docs/screenshots/08d-preview-pdf.png",l="/filebox/docs/screenshots/08e-preview-csv.png",g=JSON.parse('{"title":"预览","description":"","frontmatter":{},"headers":[],"relativePath":"features/preview.md","filePath":"features/preview.md","lastUpdated":1791393728000}'),p={name:"features/preview.md"};function h(f,t,_,m,b,u){return r(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="预览" tabindex="-1">预览 <a class="header-anchor" href="#预览" aria-label="Permalink to &quot;预览&quot;">​</a></h1><p>点击文件即可在工作区内预览，无需先下载到笔记本。桌面为多标签工作区；手机上预览全屏切换。</p><h2 id="图片" tabindex="-1">图片 <a class="header-anchor" href="#图片" aria-label="Permalink to &quot;图片&quot;">​</a></h2><p>缩放、平移；工具条可调缩放比例。</p><p><img src="'+i+'" alt="图片预览 plot.png"></p><h2 id="markdown-文本" tabindex="-1">Markdown / 文本 <a class="header-anchor" href="#markdown-文本" aria-label="Permalink to &quot;Markdown / 文本&quot;">​</a></h2><p>Markdown 渲染；纯文本与代码走语法高亮编辑器（只读：查找、换行）。</p><p><img src="'+s+'" alt="Markdown 预览"></p><p><img src="'+n+'" alt="代码预览 hello.py"></p><h2 id="pdf" tabindex="-1">PDF <a class="header-anchor" href="#pdf" aria-label="Permalink to &quot;PDF&quot;">​</a></h2><p>内置 PDF 查看器，支持 Adaptive / 百分比缩放。</p><p><img src="'+c+'" alt="PDF 预览"></p><h2 id="csv-tsv" tabindex="-1">CSV / TSV <a class="header-anchor" href="#csv-tsv" aria-label="Permalink to &quot;CSV / TSV&quot;">​</a></h2><p>表格渲染，显示行列数与分隔符；可切换 Raw / Copy。</p><p><img src="'+l+'" alt="CSV 预览"></p><h2 id="office-可选" tabindex="-1">Office（可选） <a class="header-anchor" href="#office-可选" aria-label="Permalink to &quot;Office（可选）&quot;">​</a></h2><p>Word / PowerPoint 经 Agent 上 LibreOffice 转为 PDF 后预览；表格导出为每 sheet 一份 CSV。需配置 <code>FILEBOX_AGENT_SOFFICE</code>，见 <a href="/filebox/docs/ops/office">Office 预览</a>。</p><p><img src="'+e+'" alt="PowerPoint → PDF 预览"></p><p>Settings 里有 <strong>Office preview</strong> 开关（浏览器本地偏好，默认开）。</p><h2 id="支持类型一览" tabindex="-1">支持类型一览 <a class="header-anchor" href="#支持类型一览" aria-label="Permalink to &quot;支持类型一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>行为</th></tr></thead><tbody><tr><td>图片</td><td>缩放平移（含 TIFF）</td></tr><tr><td>PDF</td><td>内置查看器</td></tr><tr><td>Markdown</td><td>渲染</td></tr><tr><td>代码 / 文本 / 日志</td><td>Monaco 只读</td></tr><tr><td>HTML</td><td>沙箱会话</td></tr><tr><td>CSV / TSV</td><td>表格</td></tr><tr><td>Word / PPT</td><td>可选：Agent 侧 → PDF</td></tr><tr><td>Excel / ODS</td><td>可选：每 sheet → CSV</td></tr></tbody></table><h2 id="提示" tabindex="-1">提示 <a class="header-anchor" href="#提示" aria-label="Permalink to &quot;提示&quot;">​</a></h2><ul><li>桌面多标签；可关闭、切换；支持键盘快捷键。</li><li>过大文件会先询问，避免拖死浏览器。</li><li>预览栏可直接 <strong>Download</strong>。</li><li>无 <code>soffice</code> 时 Office 仍可下载，预览入口不可用。</li></ul>',23)])])}const x=a(p,[["render",h]]);export{g as __pageData,x as default};
